.settings-sidebar {
    width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.5rem 0;
    min-height: 100%;
}

.sidebar-title {
    padding: 0 1.25rem 1rem;
    margin: 0;
    font-weight: 600;
    color: #495057;
    border-bottom: 1px solid #dee2e6;
}

.settings-nav {
    display: flex;
    flex-direction: column;
    padding-top: 0.5rem;
}

.nav-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    border: none;
    background: transparent;
    text-align: left;
    font-size: 0.95rem;
    color: #495057;
    cursor: pointer;
    transition: background-color 0.15s, color 0.15s;
}

.nav-item:hover {
    background: #e9ecef;
}

.nav-item.active {
    background: #0d6efd;
    color: #fff;
    font-weight: 500;
}

.nav-icon {
    font-size: 1.1rem;
}

@using sv_00a4bd294db44f72b94663cf00be7467.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h3>Profile</h3>

    @if (_loading)
    {
        <p>Loading profile...</p>
    }
    else
    {
        <div class="profile-layout">
            <div class="avatar-area">
                <div class="avatar-preview">
                    @if (!string.IsNullOrWhiteSpace(_avatarUrl))
                    {
                        <img src="@_avatarUrl" alt="Avatar" />
                    }
                    else
                    {
                        <span class="avatar-placeholder">👤</span>
                    }
                </div>
                <span class="avatar-url-label" title="@_avatarUrl">@TruncateUrl(_avatarUrl)</span>
            </div>

            <div class="profile-fields">
                <div class="field-group">
                    <label for="displayName">Display Name</label>
                    <input id="displayName" type="text" class="form-control" @bind="_displayName" />
                </div>

                <div class="field-group">
                    <label for="email">Email</label>
                    <input id="email" type="email" class="form-control" @bind="_email" />
                </div>

                <div class="field-group">
                    <label for="bio">Bio</label>
                    <textarea id="bio" class="form-control" rows="4" @bind="_bio"></textarea>
                </div>

                <div class="button-group">
                    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                        @(_saving ? "Saving..." : "Save Changes")
                    </button>
                    <button class="btn btn-outline-secondary" @onclick="Discard">Discard Changes</button>
                </div>

                @if (_successMessage is not null)
                {
                    <div class="toast-message success">@_successMessage</div>
                }
                @if (_errorMessage is not null)
                {
                    <div class="toast-message error">@_errorMessage</div>
                }
            </div>
        </div>
    }
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;
    private string? _errorMessage;

    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private string _avatarUrl = "";

    private UserProfile? _savedProfile;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
    }

    private async Task LoadProfileAsync()
    {
        _loading = true;
        try
        {
            _savedProfile = await SettingsService.GetProfileAsync();
            ApplyProfile(_savedProfile);
        }
        finally
        {
            _loading = false;
        }
    }

    private void ApplyProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _bio = profile.Bio;
        _avatarUrl = profile.AvatarUrl;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _successMessage = null;
        _errorMessage = null;
        try
        {
            var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
            await SettingsService.SaveProfileAsync(updated);
            _savedProfile = updated;
            _successMessage = "Profile saved successfully!";
        }
        catch (Exception ex)
        {
            _errorMessage = $"Failed to save: {ex.Message}";
        }
        finally
        {
            _saving = false;
        }
    }

    private void Discard()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
        _successMessage = null;
        _errorMessage = null;
    }

    private static string TruncateUrl(string? url)
    {
        if (string.IsNullOrWhiteSpace(url)) return "(no avatar)";
        return url.Length > 40 ? url[..37] + "..." : url;
    }
}

.profile-layout {
    display: flex;
    gap: 2rem;
}

.avatar-area {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
}

.avatar-preview {
    width: 120px;
    height: 120px;
    border-radius: 50%;
    border: 2px solid #dee2e6;
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #f8f9fa;
}

.avatar-preview img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    font-size: 3rem;
}

.avatar-url-label {
    font-size: 0.8rem;
    color: #6c757d;
    max-width: 140px;
    text-align: center;
    word-break: break-all;
}

.profile-fields {
    flex: 1;
}

@using sv_00a4bd294db44f72b94663cf00be7467.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h3>Notifications</h3>

    @if (_loading)
    {
        <p>Loading notification preferences...</p>
    }
    else
    {
        <div class="toggle-group">
            <label class="toggle-row">
                <span>Email Notifications</span>
                <input type="checkbox" class="form-check-input" @bind="_emailNotifications" />
            </label>
            <label class="toggle-row">
                <span>Push Notifications</span>
                <input type="checkbox" class="form-check-input" @bind="_pushNotifications" />
            </label>
            <label class="toggle-row">
                <span>Weekly Digest</span>
                <input type="checkbox" class="form-check-input" @bind="_weeklyDigest" />
            </label>
        </div>

        <h5 class="mt-4">Muted Channels</h5>
        @if (_channels.Count == 0)
        {
            <p class="text-muted">No channels available.</p>
        }
        else
        {
            <div class="channel-list">
                @foreach (var channel in _channels)
                {
                    <label class="channel-row">
                        <input type="checkbox"
                               class="form-check-input"
                               checked="@channel.Muted"
                               @onchange="e => channel.Muted = (bool)(e.Value ?? false)" />
                        <span>@channel.Name</span>
                    </label>
                }
            </div>
        }

        <div class="button-group mt-3">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving..." : "Save Preferences")
            </button>
        </div>

        @if (_message is not null)
        {
            <div class="toast-message @(_isError ? "error" : "success")">@_message</div>
        }
    }
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _message;
    private bool _isError;

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<ChannelState> _channels = [];

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        try
        {
            var prefs = await SettingsService.GetNotificationPrefsAsync();
            _emailNotifications = prefs.EmailNotifications;
            _pushNotifications = prefs.PushNotifications;
            _weeklyDigest = prefs.WeeklyDigest;
            _channels = prefs.MutedChannels.Select(c => new ChannelState(c, true)).ToList();
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = null;
        try
        {
            var mutedChannels = _channels.Where(c => c.Muted).Select(c => c.Name).ToList();
            var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, mutedChannels);
            await SettingsService.SaveNotificationPrefsAsync(prefs);
            _message = "Notification preferences saved!";
            _isError = false;
        }
        catch (Exception ex)
        {
            _message = $"Failed to save: {ex.Message}";
            _isError = true;
        }
        finally
        {
            _saving = false;
        }
    }

    private class ChannelState(string name, bool muted)
    {
        public string Name { get; } = name;
        public bool Muted { get; set; } = muted;
    }
}

.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.toggle-row {
    display: flex;
