toolArgs.file_text:
@using sv_00a4bd294db44f72b94663cf00be7467.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h3>Security</h3>

    @if (_loading)
    {
        <p>Loading security settings...</p>
    }
    else
    {
        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => _passwordExpanded = !_passwordExpanded">
                <span>🔑 Change Password</span>
                <span class="expand-icon">@(_passwordExpanded ? "▲" : "▼")</span>
            </button>
            @if (_passwordExpanded)
            {
                <div class="panel-body">
                    <div class="field-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" class="form-control" @bind="_currentPassword" />
                    </div>
                    <div class="field-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" class="form-control" @bind="_newPassword" />
                    </div>
                    <div class="field-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" class="form-control" @bind="_confirmPassword" />
                    </div>
                    <button class="btn btn-primary mt-2" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                        @(_changingPassword ? "Updating..." : "Update Password")
                    </button>
                    @if (_passwordMessage is not null)
                    {
                        <div class="toast-message @(_passwordIsError ? "error" : "success")">@_passwordMessage</div>
                    }
                </div>
            }
        </div>

        @if (_lastPasswordChange is not null)
        {
            <p class="text-muted mt-2 mb-3">Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }

        <!-- Two-Factor Authentication -->
        <div class="toggle-row mt-3">
            <div>
                <span>Two-Factor Authentication</span>
                <span class="status-indicator @(_twoFactorEnabled ? "enabled" : "disabled")">
                    @(_twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            <input type="checkbox" class="form-check-input" @bind="_twoFactorEnabled" />
        </div>

        <!-- Active Sessions -->
        <h5 class="mt-4">Active Sessions</h5>
        @if (_sessions.Count == 0)
        {
            <p class="text-muted">No active sessions.</p>
        }
        else
        {
            <div class="table-responsive">
                <table class="table table-striped">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in _sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td>
                                    @if (session != _sessions[0])
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => PromptRevoke(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="badge bg-success">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        }

        @if (_revokeTarget is not null)
        {
            <RevokeSessionDialog Session="_revokeTarget"
                                 OnConfirm="ConfirmRevokeAsync"
                                 OnCancel="CancelRevoke" />
        }
    }
</div>

@code {
    private bool _loading = true;
    private bool _passwordExpanded;
    private bool _changingPassword;
    private string? _passwordMessage;
    private bool _passwordIsError;

    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";

    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = [];
    private ActiveSession? _revokeTarget;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        try
        {
            var settings = await SettingsService.GetSecuritySettingsAsync();
            _twoFactorEnabled = settings.TwoFactorEnabled;
            _lastPasswordChange = settings.LastPasswordChange;
            _sessions = settings.Sessions.ToList();
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task ChangePasswordAsync()
    {
        _passwordMessage = null;
        if (_newPassword != _confirmPassword)
        {
            _passwordMessage = "Passwords do not match.";
            _passwordIsError = true;
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordMessage = "New password cannot be empty.";
            _passwordIsError = true;
            return;
        }

        _changingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _passwordMessage = "Password updated successfully!";
            _passwordIsError = false;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _passwordMessage = $"Failed: {ex.Message}";
            _passwordIsError = true;
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private void PromptRevoke(ActiveSession session) => _revokeTarget = session;
    private void CancelRevoke() => _revokeTarget = null;

    private async Task ConfirmRevokeAsync()
    {
        if (_revokeTarget is null) return;
        try
        {
            await SettingsService.RevokeSessionAsync(_revokeTarget.Id);
            _sessions.Remove(_revokeTarget);
        }
        catch
        {
            // Could show error — keeping simple
        }
        finally
        {
            _revokeTarget = null;
        }
    }
}

