toolArgs.file_text:
.expandable-panel {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.875rem 1rem;
    border: none;
    background: #f8f9fa;
    font-weight: 500;
    cursor: pointer;
}

.panel-header:hover {
    background: #e9ecef;
}

.expand-icon {
    font-size: 0.75rem;
    color: #6c757d;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #dee2e6;
}

.toggle-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border-radius: 0.5rem;
}

.status-indicator {
    font-size: 0.8rem;
    padding: 0.15rem 0.5rem;
    border-radius: 1rem;
    margin-left: 0.75rem;
}

.status-indicator.enabled {
    background: #d1e7dd;
    color: #0f5132;
}

.status-indicator.disabled {
    background: #f8d7da;
    color: #842029;
