toolArgs.file_text:
@using sv_00a4bd294db44f72b94663cf00be7467.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h3>Appearance</h3>

    @if (_loading)
    {
        <p>Loading appearance settings...</p>
    }
    else
    {
        <div class="appearance-layout">
            <div class="appearance-controls">
                <!-- Theme -->
                <div class="field-group">
                    <label><strong>Theme</strong></label>
                    <div class="radio-group">
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <label class="radio-option">
                                <input type="radio" name="theme" value="@theme"
                                       checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <span>@theme</span>
                            </label>
                        }
                    </div>
                </div>

                <!-- Font Size -->
                <div class="field-group">
                    <label><strong>Font Size</strong></label>
                    <div class="radio-group">
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <label class="radio-option">
                                <input type="radio" name="fontSize" value="@size"
                                       checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <span>@size</span>
                            </label>
                        }
                    </div>
                </div>

                <!-- Language -->
                <div class="field-group">
                    <label for="language"><strong>Language</strong></label>
                    <select id="language" class="form-select" @bind="_language">
                        <option value="en">English</option>
                        <option value="es">Español</option>
                        <option value="fr">Français</option>
                        <option value="de">Deutsch</option>
                        <option value="ja">日本語</option>
                        <option value="zh">中文</option>
                    </select>
                </div>

                <!-- Compact Mode -->
                <label class="toggle-row">
                    <span><strong>Compact Mode</strong></span>
                    <input type="checkbox" class="form-check-input" @bind="_compactMode" />
                </label>

                <div class="button-group mt-3">
                    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                        @(_saving ? "Saving..." : "Save")
                    </button>
                </div>

                @if (_message is not null)
                {
                    <div class="toast-message @(_isError ? "error" : "success")">@_message</div>
                }
            </div>

            <!-- Live Preview -->
            <div class="preview-area @PreviewThemeClass" style="font-size: @PreviewFontSize; padding: @PreviewPadding;">
                <h5>Live Preview</h5>
                <p>This is how your content will look with the selected settings.</p>
                <div class="preview-card">
                    <strong>Sample Card</strong>
                    <p>Theme: @_theme · Font: @_fontSize · Language: @GetLanguageName(_language)</p>
                    <button class="btn btn-sm btn-primary">Sample Button</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _message;
    private bool _isError;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    private string PreviewThemeClass => _theme switch
    {
        "Dark" => "preview-dark",
        _ => "preview-light"
    };

    private string PreviewFontSize => _fontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.15rem",
        _ => "1rem"
    };

    private string PreviewPadding => _compactMode ? "0.75rem" : "1.5rem";

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        try
        {
            var settings = await SettingsService.GetAppearanceAsync();
            _theme = settings.Theme;
            _fontSize = settings.FontSize;
            _language = settings.Language;
            _compactMode = settings.CompactMode;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = null;
        try
        {
            var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            _message = "Appearance settings saved!";
            _isError = false;
        }
        catch (Exception ex)
        {
            _message = $"Failed to save: {ex.Message}";
            _isError = true;
        }
        finally
        {
            _saving = false;
        }
    }

    private static string GetLanguageName(string code) => code switch
    {
        "en" => "English",
        "es" => "Español",
        "fr" => "Français",
        "de" => "Deutsch",
        "ja" => "日本語",
        "zh" => "中文",
        _ => code
    };
}

