toolArgs.file_text:
.appearance-layout {
    display: flex;
    gap: 2rem;
}

.appearance-controls {
    flex: 1;
}

.radio-group {
    display: flex;
    gap: 1.25rem;
    margin-top: 0.25rem;
}

.radio-option {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

.toggle-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border-radius: 0.5rem;
    cursor: pointer;
}

.preview-area {
    flex: 1;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    min-height: 200px;
    transition: all 0.2s;
}

.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-dark {
    background: #212529;
    color: #f8f9fa;
}

.preview-dark .preview-card {
    background: #343a40;
    border-color: #495057;
}

.preview-card {
    margin-top: 1rem;
    padding: 1rem;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    background: #f8f9fa;
}

